20	+using Microsoft.EntityFrameworkCore;
21	+using seed_b_backend.Api.Data;
22	+using seed_b_backend.Api.Domain;
23	+
24	+namespace seed_b_backend.Api.Application;
25	+
26	+public class RatingService(AppDbContext context)
27	+{
28	+    public async Task<RatingAggregate?> SubmitRatingAsync(
29	+        string productId,
30	+        string authorName,
31	+        int score,
32	+        CancellationToken ct = default)
33	+    {
34	+        authorName = authorName.Trim();
35	+
36	+        var productExists = await context.Products.AnyAsync(p => p.Id == productId, ct);
37	+        if (!productExists)
38	+        {
39	+            return null;
40	+        }
41	+
42	+        var updatedRows = await context.Ratings
43	+            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
44	+            .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
45	+
46	+        if (updatedRows == 0)
47	+        {
48	+            var newRating = new Rating { ProductId = productId, AuthorName = authorName, Score = score };
49	+            context.Ratings.Add(newRating);
50	+            try
51	+            {
52	+                await context.SaveChangesAsync(ct);
53	+            }
54	+            catch (DbUpdateException)
55	+            {
56	+                // Eine gleichzeitige Bewertungsabgabe für dasselbe (ProductId, AuthorName)
57	+                // hat ihre Zeile zwischen unserem ExecuteUpdateAsync (traf nichts) und
58	+                // diesem Add eingefügt — der DB-Unique-Constraint (AD-5) lehnt unseren
59	+                // Insert ab, statt still zu duplizieren. Fallback: Update, das jetzt
60	+                // garantiert genau diese Zeile trifft.
61	+                context.Entry(newRating).State = EntityState.Detached;
62	+                var raceFallbackRows = await context.Ratings
63	+                    .Where(r => r.ProductId == productId && r.AuthorName == authorName)
64	+                    .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
65	+
66	+                // Traf der Fallback keine Zeile, war die Ursache kein AD-5-Race (der hätte
67	+                // die Zeile ja gerade erst angelegt) — z. B. ein FK-Verstoß, weil das Produkt
68	+                // zwischen der Existenzprüfung oben und diesem SaveChangesAsync extern
69	+                // gelöscht wurde. In dem Fall NICHT still Erfolg vortäuschen.
70	+                if (raceFallbackRows == 0)
71	+                {
72	+                    throw;
73	+                }
74	+            }
75	+        }
76	+
77	+        var scores = await context.Ratings
78	+            .Where(r => r.ProductId == productId)
79	+            .Select(r => r.Score)
80	+            .ToListAsync(ct);
81	+
82	+        return new RatingAggregate
83	+        {
84	+            AverageRating = scores.Count > 0 ? scores.Average() : null,
85	+            RatingCount = scores.Count
86	+        };
87	+    }
88	+}
